import pandas as pd
ISO, DMY = '%Y-%m-%d %H:%M:%S', '%d/%m/%Y %H:%M'

def ingest(path):
    return pd.read_csv(path, dtype=str)

def parse_times(df):
    t = df.timestamp
    iso = pd.to_datetime(t, format=ISO, errors='coerce')
    dmy = pd.to_datetime(t, format=DMY, errors='coerce')
    return df.assign(ts=iso.fillna(dmy))

raw = ingest('mobile_money_log.csv')
log = parse_times(raw)
print(len(raw), 'rows', log.ts.isna().sum(), 'bad times')
print(raw.timestamp.str.contains('/').sum(), 'day first')

WANT = ('txn_id timestamp msisdn_hash agent_id '
        'amount_ugx type status').split()

class SchemaDrift(Exception):
    pass

def alert(kind, owner, text):
    return f'ALERT {kind} | {owner} | {text}'

def check_schema(raw):
    gone = [c for c in WANT if c not in raw.columns]
    if gone:
        raise SchemaDrift(alert('schema', 'platform lead',
                                f'{gone[0]} is missing'))

check_schema(raw)
print('schema ok')

