def publish(clean, folder, keyed=True):
    f = pathlib.Path(folder) / 'clean.csv'
    if f.exists():
        clean = pd.concat([pd.read_csv(f, dtype=str), clean])
        if keyed:
            clean = clean.drop_duplicates('txn_id', keep='last')
    clean.sort_values('txn_id').to_csv(f, index=False)
    return len(clean)

